window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-23901\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοτύλων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3116 na letra κ · nº geral 23901</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ébrio; bêbado. 〈κοτύλη〉</p></section></article>\n<article id=\"entry-dgp-23902\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοὐ</h1><div class=\"entry-meta\"><span>DGP · ordem 3117 na letra κ · nº geral 23902</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de καὶ οὐκ.</p></section></article>\n<article id=\"entry-dgp-23903\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοῦ, κού</h1><div class=\"entry-meta\"><span>DGP · ordem 3118 na letra κ · nº geral 23903</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ποῦ, πού.</p></section></article>\n<article id=\"entry-dgp-23904\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοὐδέ, κοὐδείς</h1><div class=\"entry-meta\"><span>DGP · ordem 3119 na letra κ · nº geral 23904</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de καὶ οὐδέ, καὶ οὐδείς.</p></section></article>\n<article id=\"entry-dgp-23905\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοὐκ</h1><div class=\"entry-meta\"><span>DGP · ordem 3120 na letra κ · nº geral 23905</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de καὶ οὐκ.</p></section></article>\n<article id=\"entry-dgp-23906\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοὐκέτι</h1><div class=\"entry-meta\"><span>DGP · ordem 3121 na letra κ · nº geral 23906</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de καὶ οὐκέτι.</p></section></article>\n<article id=\"entry-dgp-23907\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουλεόν</h1><div class=\"entry-meta\"><span>DGP · ordem 3122 na letra κ · nº geral 23907</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. e jôn. = κολέον.</p></section></article>\n<article id=\"entry-dgp-23908\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κούνικλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3123 na letra κ · nº geral 23908</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">coelho. [lat.]</p></section></article>\n<article id=\"entry-dgp-23909\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοὔποτε, κοὔπω</h1><div class=\"entry-meta\"><span>DGP · ordem 3124 na letra κ · nº geral 23909</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de καὶ οὔποτε, καὶ οὔπω.</p></section></article>\n<article id=\"entry-dgp-23910\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουρά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3125 na letra κ · nº geral 23910</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de cortar ou de aparar os cabelos, de tosquiar ovelha 2 ação de podar árvore, de cortar erva 3 cabeça raspada em sinal de luto 4 madeixa de cabelos cortadas 5 lã tosquiada 6 crist. tonsura. 〈κείρω〉</p></section></article>\n<article id=\"entry-dgp-23911\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουρεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3126 na letra κ · nº geral 23911</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">barbearia. 〈κουρεύς〉</p></section></article>\n<article id=\"entry-dgp-23912\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουρεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3127 na letra κ · nº geral 23912</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">barbeiro; cabeleireiro. 〈κείρω〉</p></section></article>\n<article id=\"entry-dgp-23913\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουρεύτρια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3128 na letra κ · nº geral 23913</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de κουρεύς.</p></section></article>\n<article id=\"entry-dgp-23914\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κούρη</h1><div class=\"entry-meta\"><span>DGP · ordem 3129 na letra κ · nº geral 23914</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = κόρη.</p></section></article>\n<article id=\"entry-dgp-23915\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουρή</h1><div class=\"entry-meta\"><span>DGP · ordem 3130 na letra κ · nº geral 23915</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = κουρά.</p></section></article>\n<article id=\"entry-dgp-23916\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κούρητες, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3131 na letra κ · nº geral 23916</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jovens guerreiros. 〈κοῦρος〉</p></section></article>\n<article id=\"entry-dgp-23917\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κουρῆτες, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3132 na letra κ · nº geral 23917</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Curetes, antigos habitantes de Plêuron na Etólia 2 Curetes, nome de divindades benfazejas da Ásia Menor e de Creta, e dos sacerdotes de Zeus e de Cibele.</p></section></article>\n<article id=\"entry-dgp-23918\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κουρητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3133 na letra κ · nº geral 23918</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dos Curetes. 〈Κουρῆτες〉</p></section></article>\n<article id=\"entry-dgp-23919\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουρίας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 3134 na letra κ · nº geral 23919</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de cabelos cortados. 〈κουρά〉</p></section></article>\n<article id=\"entry-dgp-23920\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουριάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3135 na letra κ · nº geral 23920</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 (cabelo, barba) ter necessidade de corte 2 ter barba ou cabelos muito longos. 〈κουρά〉</p></section></article>\n<article id=\"entry-dgp-23921\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουρίδιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3136 na letra κ · nº geral 23921</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 unido por casamento: κ. ἀνήρ hom. esposo legítimo, κουριδία γυνή hom. esposa legítima 2 de esposos legítimos: λέχος κουρίδιον hom. leito conjugal 3 de jovem esposo ♦ ὁ κουρίδιος 4 esposo. 〈κοῦρος〉</p></section></article>\n<article id=\"entry-dgp-23922\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3137 na letra κ · nº geral 23922</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 educar até à juventude 2 intr. atingir a juventude; chegar à juventude; ser jovem. 〈κοῦρος〉</p></section></article>\n<article id=\"entry-dgp-23923\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3138 na letra κ · nº geral 23923</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que serve para cortar ou aparar. 〈κουρά〉</p></section></article>\n<article id=\"entry-dgp-23924\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κούριμος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3139 na letra κ · nº geral 23924</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que serve para tosar, cortar ou aparar 2 tosquiado; raspado. 〈κουρά〉</p></section></article>\n<article id=\"entry-dgp-23925\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κούριξ</h1><div class=\"entry-meta\"><span>DGP · ordem 3140 na letra κ · nº geral 23925</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. pelos cabelos. 〈κουρά〉</p></section></article>\n<article id=\"entry-dgp-23926\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουρίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 3141 na letra κ · nº geral 23926</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem) 1 que corta; que tosa ♦ ἡ κουρίς 2 cabeleireira. 〈κουρά〉</p></section></article>\n<article id=\"entry-dgp-23927\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουροβόρος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3142 na letra κ · nº geral 23927</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">duv. que devora jovens ou de jovens devorados. 〈κοῦρος, βιβρώσκω〉</p></section></article>\n<article id=\"entry-dgp-23928\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοῦρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3143 na letra κ · nº geral 23928</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = κόρος2.</p></section></article>\n<article id=\"entry-dgp-23929\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουρότερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3144 na letra κ · nº geral 23929</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mais jovem; jovem. 〈κοῦρος〉</p></section></article>\n<article id=\"entry-dgp-23930\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουροτρόφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3145 na letra κ · nº geral 23930</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nutriz de jovens (país, divindade, mulher). 〈κοῦρος, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-23931\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουστωδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3146 na letra κ · nº geral 23931</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. guarda; guarnição. [lat.]</p></section></article>\n<article id=\"entry-dgp-23932\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοὔτε</h1><div class=\"entry-meta\"><span>DGP · ordem 3147 na letra κ · nº geral 23932</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de καὶ οὔτε e de καὶ οὔ τε.</p></section></article>\n<article id=\"entry-dgp-23933\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοὔτοι</h1><div class=\"entry-meta\"><span>DGP · ordem 3148 na letra κ · nº geral 23933</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de καὶ οὔτοι.</p></section></article>\n<article id=\"entry-dgp-23934\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουφίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3149 na letra κ · nº geral 23934</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. át. κουφιῶ) 1 intr. ser leve 2 estar aliviado; experimentar alívio; sentir-se melhor 3 tornar leve; aliviar; diminuir (encargos, impostos): κ. τόκων τοὺς χρεωφειλέτας plut. aliviar os devedores quanto à carga dos juros, κ. τὰ ὀφλήματα plut. diminuir as dívidas 4 proporcionar alívio: κ. τοὺς νοσοῦντας plut. aliviar os doentes 5 consolar 6 levantar: ἀσπίδα κ. eur. erguer o escudo, με κουφίσας πρόσλαβε sóf. ergue-me e apóia-me, ἅλμα κ. sóf., πήδεμα κ. eur. saltar livremente ou rapidamente, alçar-se num salto. 〈κοῦφος〉</p></section></article>\n<article id=\"entry-dgp-23935\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κούφισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3150 na letra κ · nº geral 23935</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alívio; consolo. 〈κουφίζω〉</p></section></article>\n<article id=\"entry-dgp-23936\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κούφισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3151 na letra κ · nº geral 23936</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κούφισις.</p></section></article>\n<article id=\"entry-dgp-23937\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουφισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3152 na letra κ · nº geral 23937</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κούφισις.</p></section></article>\n<article id=\"entry-dgp-23938\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουφολογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3153 na letra κ · nº geral 23938</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">palavra dita irrefletidamente. 〈κου­φολόγος〉</p></section></article>\n<article id=\"entry-dgp-23939\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουφολόγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3154 na letra κ · nº geral 23939</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que fala irrefletidamente; inconseqüente. 〈κοῦφος, λέγω〉</p></section></article>\n<article id=\"entry-dgp-23940\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουφόνοος-ους, οος-ους, οον-ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 3155 na letra κ · nº geral 23940</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de natureza ligeira; de vôo ligeiro (pássaro) 2 irrefletido; imprudente 3 crédulo 4 volúvel; inconstante. 〈κοῦφος, νόος〉</p></section></article>\n<article id=\"entry-dgp-23941\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοῦφος, η</h1><div class=\"entry-meta\"><span>DGP · ordem 3156 na letra κ · nº geral 23941</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, dór. α, ον 1 Mil. armado à ligeira; leve; não carregado: κούφη στρατιά plut. tropas ligeiras 2 leve; que não pesa; fácil de levar ou suportar: κουφότερα ὅπλα xen. armamento ligeiro, κούφα σοι χθὼν ἐπάνωθε πέσοι eur. que a terra caia leve sobre ti, ἡ εὔκλεια κουφότερα φέρειν xen. a boa fama é mais leve de carregar, κούφη βασι­λεία isócr. realeza fácil de suportar 3 Medic. leve; de fácil digestão (alimento) 4 de bom caráter (pessoa) 5 de andadura leve; de passos ligeiros; veloz: κ. πούς sóf. pé ligeiro 6 livre de preocupações; despreocupado 7 leve; vazio; vão: κούφη ἐλπίς tuc. vã esperança 8 leve; de pouca importância: κοῦφα ἁμαρτήματα plat. faltas leves ♦ κοῦφα adv. 9 com agilidade; agilmente: κ. βιβῶν pínd. marchando agilmente, κ. ποσὶ προβιβάς hom. avançando com passos rápidos ♦ τὸ κοῦφον 10 leviandade.</p></section></article>\n<article id=\"entry-dgp-23942\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουφότης, ητος,</h1><div class=\"entry-meta\"><span>DGP · ordem 3157 na letra κ · nº geral 23942</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. κουφοτής, ῆτος (ἡ) 1 facilidade de digestão; digestibilidade: κ. τροφῆς teofr. digestibilidade do alimento 2 leviandade 3 alívio. 〈κοῦφος〉</p></section></article>\n<article id=\"entry-dgp-23943\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κούφως</h1><div class=\"entry-meta\"><span>DGP · ordem 3158 na letra κ · nº geral 23943</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 levemente; sem sobrecarga: ἄνθρωποι κ. ἐσκευασμένοι tuc. homens equipados à ligeira 2 sem dificuldade; sem fadiga; sem sofrimento: κ. φέρειν eur. suportar facilmente 3 com um passo ligeiro; agilmente 4 de coração leve.</p></section></article>\n<article id=\"entry-dgp-23944\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοὐχ, κοὐχί</h1><div class=\"entry-meta\"><span>DGP · ordem 3159 na letra κ · nº geral 23944</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de καὶ οὐκ, καὶ οὐχί.</p></section></article>\n<article id=\"entry-dgp-23945\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόφινος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3160 na letra κ · nº geral 23945</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cesto 2 medida beócia para líquidos e grãos, equiv. a 3 quênices.</p></section></article>\n<article id=\"entry-dgp-23946\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοχλίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3161 na letra κ · nº geral 23946</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 concha em espiral; caracol 2 escada em espiral 3 parafuso de Arquimedes, cabrestante para puxar água. 〈κόχλος〉</p></section></article>\n<article id=\"entry-dgp-23947\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοχλίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3162 na letra κ · nº geral 23947</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de κοχλίας.</p></section></article>\n<article id=\"entry-dgp-23948\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοχλιώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 3163 na letra κ · nº geral 23948</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">em forma de caracol; espiralado. 〈κοχ­λίας, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-23949\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόχλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3164 na letra κ · nº geral 23949</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 concha em espiral 2 concha marinha 3 concha da qual se extraía a púrpura 4 caracol.</p></section></article>\n<article id=\"entry-dgp-23950\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοχώνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3165 na letra κ · nº geral 23950</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nádegas.</p></section></article>\n<article id=\"entry-dgp-23951\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κόωνδε</h1><div class=\"entry-meta\"><span>DGP · ordem 3166 na letra κ · nº geral 23951</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em direção a Cós. 〈Κόως, -δε〉</p></section></article>\n<article id=\"entry-dgp-23952\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κόως</h1><div class=\"entry-meta\"><span>DGP · ordem 3167 na letra κ · nº geral 23952</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Κῶς.</p></section></article>\n<article id=\"entry-dgp-23953\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράββατος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3168 na letra κ · nº geral 23953</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">leito miserável; catre.</p></section></article>\n<article id=\"entry-dgp-23954\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραγγάνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3169 na letra κ · nº geral 23954</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) soltar gritos. 〈κράζω〉</p></section></article>\n<article id=\"entry-dgp-23955\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραδαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3170 na letra κ · nº geral 23955</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e aor. ἐκράδανα; pas. só pres. e aor. ἐκραδάνθην) 1 balançar para lançar; brandir (arma) 2 sacudir; agitar: κ. χθόνα ésql. abalar a terra 3 fazer tremer; abalar: κ. τὴν Πελοπόννησον plut. fazer tremer o Peloponeso ♦ pas. 4 ser agitado; tremer 5 tremer de medo por algo, ἐπί e dat.</p></section></article>\n<article id=\"entry-dgp-23956\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραδάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3171 na letra κ · nº geral 23956</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres.) = κραδαίνω.</p></section></article>\n<article id=\"entry-dgp-23957\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράδη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3172 na letra κ · nº geral 23957</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 extremidade do galho (de árvore, partic. de figueira) 2 ramo da figueira 3 figueira 4 doença de plantas 5 Dram. mecanismo cênico usado para elevar os atores acima do palco.</p></section></article>\n<article id=\"entry-dgp-23958\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραδηφορία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3173 na letra κ · nº geral 23958</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">festa judia em que se levavam ramos de figueira. 〈κράδη, φέρω〉</p></section></article>\n<article id=\"entry-dgp-23959\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραδία</h1><div class=\"entry-meta\"><span>DGP · ordem 3174 na letra κ · nº geral 23959</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn., κραδίη poét. = καρδία.</p></section></article>\n<article id=\"entry-dgp-23960\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3175 na letra κ · nº geral 23960</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κεκράξομαι, aor.2 ἔκραγον, aor.1 ἔκραξα, perf. com sent. pres. κέκραγα) 1 (animal) soltar um grito rouco ou gutural 2 gritar fortemente; vociferar algo, ac. ou or. conj. (ὡς): κ. ὑπέρφρονα sóf. lançar com força palavras arrogantes, κεκραγὼς ὡς ἐν δημοκρατίᾳ δεινὰ ποιῶ dem. gritando que faço, numa democracia, coisas terríveis 3 chamar aos gritos alguém, πρός e ac. 4 pedir aos gritos algo, ac.</p></section></article>\n<article id=\"entry-dgp-23961\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραιαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3176 na letra κ · nº geral 23961</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. 3ª sing. κραίαινεν, aor. ἐκρήηνα, imper. κρήηνον, 2ª pl. κρηήνατε, inf. κρηῆναι; pas. aor. 3ª pl. ἐκράανθεν, perf. 3ª pl. κεκράανται, m.-q.-perf. 3ª pl. κεκράαντο) ép. = κραίνω.</p></section></article>\n<article id=\"entry-dgp-23962\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3177 na letra κ · nº geral 23962</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κρανῶ, aor. ἔκρανα, perf. desus.; pas. aor. ἐκράν­θην) 1 acabar; cumprir; realizar: κρ. ἐέλδωρ hom. realizar um desejo, ἐκραίαινεν ἐφετμὰς Φοίβου hom. cumpria ordens de Febo, οἵ ῥ’ ἔτυμα κραίνουσιν hom. estes (sonhos) realizam coisas verdadeiras, i.e., se realizam 2 exercer o poder sobre; ser o senhor de; governar; comandar, gen., dat. ou ac.: κρ. στρατοῦ sóf. comandar um exército, σκῆπτρα κρ. sóf. ter o cetro de comando 3 ordenar; estabelecer: χρὴ πράσσειν ἃ μοῖρα Ζεύς τ’ ἔκρανε σοῦ πέρι eur. é preciso realizar as coisas que Zeus e o destino estabeleceram para ti 4 intr. chegar ao fim; terminar; cumprir-se ♦ pas. 5 (fato) cumprir-se; realizar-se.</p></section></article>\n<article id=\"entry-dgp-23963\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραιπαλάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3178 na letra κ · nº geral 23963</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter a cabeça pesada por embriaguez; estar embriagado. 〈κραιπάλη〉</p></section></article>\n<article id=\"entry-dgp-23964\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραιπάλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3179 na letra κ · nº geral 23964</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cabeça pesada de embriaguez 2 embriaguez; bebedeira.</p></section></article>\n<article id=\"entry-dgp-23965\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραιπαλώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 3180 na letra κ · nº geral 23965</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ébrio; bêbado. 〈κραιπάλη, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-23966\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραιπνός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3181 na letra κ · nº geral 23966</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 veloz; rápido 2 (vento, ardor) impetuoso; violento.</p></section></article>\n<article id=\"entry-dgp-23967\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραιπνόσυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3182 na letra κ · nº geral 23967</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se lança rápido. 〈κραιπνός, σεύομαι〉</p></section></article>\n<article id=\"entry-dgp-23968\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραιπνοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3183 na letra κ · nº geral 23968</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que transporta ou conduz rapidamente. 〈κραιπνός, φέρω〉</p></section></article>\n<article id=\"entry-dgp-23969\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραιπνῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 3184 na letra κ · nº geral 23969</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com impetuosidade; com velocidade; rapidamente.</p></section></article>\n<article id=\"entry-dgp-23970\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραῖρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3185 na letra κ · nº geral 23970</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cume; cabeça; extremidade.</p></section></article>\n<article id=\"entry-dgp-23971\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρακτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3186 na letra κ · nº geral 23971</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que grita muito. 〈κράζω〉</p></section></article>\n<article id=\"entry-dgp-23972\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρᾶμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3187 na letra κ · nº geral 23972</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mistura 2 vinho misturado com água 3 liga (de metais).</p></section></article>\n<article id=\"entry-dgp-23973\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράμβη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3188 na letra κ · nº geral 23973</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 couve 2 qualquer vegetal semelhante à couve. 〈κράμβος〉</p></section></article>\n<article id=\"entry-dgp-23974\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραμβίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3189 na letra κ · nº geral 23974</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lagarta da couve. 〈κράμβη〉</p></section></article>\n<article id=\"entry-dgp-23975\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράμβος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3190 na letra κ · nº geral 23975</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 seco; ressequido 2 sóbrio; delicado.</p></section></article>\n<article id=\"entry-dgp-23976\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κραναοί, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3191 na letra κ · nº geral 23976</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">os descendentes de Cranau, i.e., os atenienses. 〈Κραναός〉</p></section></article>\n<article id=\"entry-dgp-23977\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραναός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3192 na letra κ · nº geral 23977</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 duro; áspero 2 rochoso 3 pontudo; aguçado.</p></section></article>\n<article id=\"entry-dgp-23978\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κραναός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3193 na letra κ · nº geral 23978</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Cranau, antigo rei de Atenas: Κραναοῦ παῖδες ésql. os filhos de Cranau, i.e., os atenienses.</p></section></article>\n<article id=\"entry-dgp-23979\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρανέεσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3194 na letra κ · nº geral 23979</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. fut. méd. com sent. pas. de κραίνω.</p></section></article>\n<article id=\"entry-dgp-23980\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράνεια, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 3195 na letra κ · nº geral 23980</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. κρανείη, ης (ἡ) 1 corniso, arbusto 2 lan­ça ou vara de corniso.</p></section></article>\n<article id=\"entry-dgp-23981\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρανέϊνος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3196 na letra κ · nº geral 23981</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito de madeira do corniso. 〈κράνεια〉</p></section></article>\n<article id=\"entry-dgp-23982\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράνειος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3197 na letra κ · nº geral 23982</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κρανέϊνος.</p></section></article>\n<article id=\"entry-dgp-23983\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρανίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3198 na letra κ · nº geral 23983</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 crânio 2 cabeça.</p></section></article>\n<article id=\"entry-dgp-23984\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράνος, εος- ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3199 na letra κ · nº geral 23984</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 capacete; elmo 2 coberta (de leito).</p></section></article>\n<article id=\"entry-dgp-23985\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρανῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3200 na letra κ · nº geral 23985</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de κραίνω.</p></section></article>\n<article id=\"entry-dgp-23986\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράς, κρατός</h1><div class=\"entry-meta\"><span>DGP · ordem 3201 na letra κ · nº geral 23986</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. κράατος, dat. κράτι ép. κράατι, ac. κρᾶτα; pl. nom. κρᾶτα, gen. κράτων, dat. κρασίν e κράτεσφι, ac. pl. κρᾶτας, κρᾶτα e ép. κράατα (ὁ, ἡ e τό) 1 sing. ou pl. cabeça: ὑπὸ κράτεσφι hom. sob a cabeça 2 alto; cimo de montanha 3 borda; extremidade: ἐπὶ κρατὸς λιμένος hom. à beira do porto.</p></section></article>\n<article id=\"entry-dgp-23987\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρᾶσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3202 na letra κ · nº geral 23987</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de misturar 2 resultado da mistura; mistura, partic. de água e vinho 3 liga de metal 4 temperatura; clima 5 temperamento; constituição física e moral; índole 6 mistura; união; combinação: ἀήθης κρᾶσις plat. estranha mistura de prazer e de dor 7 crist. união da natureza em Cristo 8 Gram. crase. 〈κεράννυμι〉</p></section></article>\n<article id=\"entry-dgp-23988\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρασπεδίτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3203 na letra κ · nº geral 23988</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o último componente de um coro. 〈κράσπεδον〉</p></section></article>\n<article id=\"entry-dgp-23989\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράσπεδον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3204 na letra κ · nº geral 23989</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 orla; franja (de uma veste) 2 ger. pl. extremidade; confins; fronteiras 3 sopé de montanha 4 ala de exército 5 Medic. doença da úvula. 〈κράς, πέδον〉</p></section></article>\n<article id=\"entry-dgp-23990\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρᾶτα</h1><div class=\"entry-meta\"><span>DGP · ordem 3205 na letra κ · nº geral 23990</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nom. e ac. sing. ou nom. pl., formas n. de κράς.</p></section></article>\n<article id=\"entry-dgp-23991\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραταιγύαλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3206 na letra κ · nº geral 23991</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de peças fortemente presas (couraça). 〈κράτος, γύαλον〉</p></section></article>\n<article id=\"entry-dgp-23992\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραταιΐς, ΐδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3207 na letra κ · nº geral 23992</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 força; vigor ♦ ἡ Κραταιΐς ac. -ίν 2 Crateis; Força, mãe de Cila. 〈κράτος〉</p></section></article>\n<article id=\"entry-dgp-23993\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραταίλεως, ως, ων</h1><div class=\"entry-meta\"><span>DGP · ordem 3208 na letra κ · nº geral 23993</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de pedras grossas ou fortes; rochoso. 〈κράτος, λᾶς〉</p></section></article>\n<article id=\"entry-dgp-23994\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραταιός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3209 na letra κ · nº geral 23994</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">forte; robusto; vigoroso. 〈κράτος〉</p></section></article>\n<article id=\"entry-dgp-23995\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραταιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3210 na letra κ · nº geral 23995</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. fortificar; fortalecer. 〈κραταιός〉</p></section></article>\n<article id=\"entry-dgp-23996\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραταίπεδος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3211 na letra κ · nº geral 23996</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de solo firme; duro; sólido. 〈κραταιός, πέδον〉</p></section></article>\n<article id=\"entry-dgp-23997\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραταίρινος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3212 na letra κ · nº geral 23997</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de couro forte ou espesso. 〈κραταιός, ῥινός1〉</p></section></article>\n<article id=\"entry-dgp-23998\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρατερός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3213 na letra κ · nº geral 23998</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 forte; poderoso (animal) 2 vigoroso; robusto (membro) 3 firme; sólido (objeto) 4 veemente; grave; violento (sentimento). 〈κράτος〉</p></section></article>\n<article id=\"entry-dgp-23999\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρατερόφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3214 na letra κ · nº geral 23999</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος de coração firme; corajoso. 〈κρατερός, φρήν〉</p></section></article>\n<article id=\"entry-dgp-24000\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρατερῶνυξ, υχος</h1><div class=\"entry-meta\"><span>DGP · ordem 3215 na letra κ · nº geral 24000</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 de unhas fortes; de garras robustas 2 de casco robusto (cavalo). 〈κρατερός, ὄνυξ〉</p></section></article>\n";
